-- ===================================================================================
-- DYNAMIC CAMPAIGN REPORTER (generated by BriefingRoom)
-- Writes the state of every objective to dcs.log, so the result can be uploaded
-- back to BriefingRoom to advance the dynamic campaign. Line format:
-- BRDC|token|sequence|missionTime|missionComplete|playerAircraftLost|dead/total/complete,...|W:category=used;...|L:type=lost;...
-- Weapons used and aircraft lost are counted for the player's groups (player and AI wingmen).
-- ===================================================================================

briefingRoom.dynamicCampaign = { }
briefingRoom.dynamicCampaign.token = "$TOKEN$"
briefingRoom.dynamicCampaign.sequence = 0
briefingRoom.dynamicCampaign.dead = { } -- unit names reported dead by events
briefingRoom.dynamicCampaign.tracked = { } -- unit names that existed at mission start
briefingRoom.dynamicCampaign.playerLost = { } -- player aircraft lost (unit names)
briefingRoom.dynamicCampaign.playerLostCount = 0
briefingRoom.dynamicCampaign.flight = { } -- player group units: name -> { type, loaded = { category = count } }
briefingRoom.dynamicCampaign.stock = { $STOCK$ } -- weapons at the departure airbase
briefingRoom.dynamicCampaign.stockLabels = { $STOCKLABELS$ }
briefingRoom.dynamicCampaign.stockWarning = "$STOCKWARNING$"
briefingRoom.dynamicCampaign.stockWarned = false
briefingRoom.dynamicCampaign.tookOff = { }

local function brdcSafeName(object)
  if object == nil then return nil end
  local ok, name = pcall(function() return object:getName() end)
  if ok then return name end
  return nil
end

local function brdcFindObject(name)
  local unit = Unit.getByName(name)
  if unit ~= nil then return unit end
  return StaticObject.getByName(name)
end

local function brdcIsDead(name)
  if briefingRoom.dynamicCampaign.dead[name] then return true end
  local object = brdcFindObject(name)
  if object == nil then return true end
  local ok, alive = pcall(function() return object:isExist() and object:getLife() >= 1 end)
  if not ok then return true end
  return not alive
end

-- Weapon category as tracked by the campaign stock, nil for guns and anything else
local function brdcWeaponCategory(desc)
  if desc == nil then return nil end
  if desc.category == Weapon.Category.MISSILE then
    if desc.missileCategory == Weapon.MissileCategory.AAM then return "AAM" end
    if desc.missileCategory == Weapon.MissileCategory.SAM then return nil end
    if desc.guidance == Weapon.GuidanceType.RADAR_PASSIVE then return "ARM" end
    return "AGM"
  end
  if desc.category == Weapon.Category.ROCKET then return "Rocket" end
  if desc.category == Weapon.Category.BOMB then
    if desc.guidance ~= nil and desc.guidance ~= 0 then return "GuidedBomb" end
    return "Bomb"
  end
  return nil
end

local function brdcCountWeapons(unit)
  local counts = { }
  if unit == nil then return counts end
  local ok, ammo = pcall(function() return unit:getAmmo() end)
  if not ok or ammo == nil then return counts end
  for _, entry in ipairs(ammo) do
    local category = brdcWeaponCategory(entry.desc)
    if category ~= nil then counts[category] = (counts[category] or 0) + (entry.count or 0) end
  end
  return counts
end

-- Snapshot of the weapons loaded by every unit of a player's group
local function brdcTrackFlight(playerUnit, overwrite)
  local dc = briefingRoom.dynamicCampaign
  local okGroup, group = pcall(function() return playerUnit:getGroup() end)
  if not okGroup or group == nil then return end
  for _, unit in ipairs(group:getUnits() or { }) do
    local name = brdcSafeName(unit)
    if name ~= nil and (overwrite or dc.flight[name] == nil) and not dc.playerLost[name] then
      local okType, typeName = pcall(function() return unit:getTypeName() end)
      dc.flight[name] = { type = okType and typeName or "unknown", loaded = brdcCountWeapons(unit) }
    end
  end
end

-- Warns once if the flight carries more than the departure airbase has
local function brdcCheckStock()
  local dc = briefingRoom.dynamicCampaign
  if dc.stockWarned then return end
  local loaded = { }
  for _, unitData in pairs(dc.flight) do
    for category, count in pairs(unitData.loaded) do loaded[category] = (loaded[category] or 0) + count end
  end
  local excess = { }
  for category, count in pairs(loaded) do
    if dc.stock[category] ~= nil and count > dc.stock[category] then
      table.insert(excess, (dc.stockLabels[category] or category).." "..count.."/"..dc.stock[category])
    end
  end
  if #excess > 0 then
    dc.stockWarned = true
    trigger.action.outTextForCoalition(briefingRoom.playerCoalition, dc.stockWarning.." "..table.concat(excess, ", "), 20)
  end
end

local function brdcFlightText()
  local dc = briefingRoom.dynamicCampaign
  local used = { }
  local lost = { }
  for name, unitData in pairs(dc.flight) do
    local remaining = { }
    local unit = Unit.getByName(name)
    local alive = not dc.playerLost[name] and unit ~= nil and not brdcIsDead(name)
    if alive then remaining = brdcCountWeapons(unit) else lost[unitData.type] = (lost[unitData.type] or 0) + 1 end
    for category, count in pairs(unitData.loaded) do
      local spent = count - (remaining[category] or 0)
      if spent > 0 then used[category] = (used[category] or 0) + spent end
    end
  end
  local usedText = { }
  for category, count in pairs(used) do table.insert(usedText, category.."="..count) end
  local lostText = { }
  for typeName, count in pairs(lost) do table.insert(lostText, typeName.."="..count) end
  return "|W:"..table.concat(usedText, ";").."|L:"..table.concat(lostText, ";")
end

function briefingRoom.dynamicCampaign.report()
  local dc = briefingRoom.dynamicCampaign
  dc.sequence = dc.sequence + 1
  local objectivesText = { }
  for i, objective in ipairs(briefingRoom.mission.objectives) do
    local dead = 0
    local total = 0
    for _, name in ipairs(objective.unitNames or { }) do
      if dc.tracked[name] then
        total = total + 1
        if brdcIsDead(name) then dead = dead + 1 end
      end
    end
    local complete = 0
    if objective.complete and not objective.failed then complete = 1 end
    table.insert(objectivesText, dead.."/"..total.."/"..complete)
  end
  local missionComplete = 0
  if briefingRoom.mission.complete then missionComplete = 1 end
  env.info("BRDC|"..dc.token.."|"..dc.sequence.."|"..string.format("%.0f", timer.getTime()).."|"..missionComplete.."|"..dc.playerLostCount.."|"..table.concat(objectivesText, ",")..brdcFlightText(), false)
end

local function brdcIsPlayer(unit)
  if unit == nil then return false end
  local ok, playerName = pcall(function() return unit:getPlayerName() end)
  if not ok or playerName == nil then return false end
  local okCoalition, coalitionId = pcall(function() return unit:getCoalition() end)
  return okCoalition and coalitionId == briefingRoom.playerCoalition
end

-- Player aircraft and AI wingmen of the player's groups
local function brdcMarkPlayerLost(unit)
  local name = brdcSafeName(unit)
  if name == nil then return end
  if not brdcIsPlayer(unit) and briefingRoom.dynamicCampaign.flight[name] == nil then return end
  if briefingRoom.dynamicCampaign.playerLost[name] then return end
  briefingRoom.dynamicCampaign.playerLost[name] = true
  briefingRoom.dynamicCampaign.playerLostCount = briefingRoom.dynamicCampaign.playerLostCount + 1
end

briefingRoom.dynamicCampaign.eventHandler = { }
function briefingRoom.dynamicCampaign.eventHandler:onEvent(event)
  if event == nil then return end
  if event.id == world.event.S_EVENT_DEAD or event.id == world.event.S_EVENT_CRASH or event.id == world.event.S_EVENT_UNIT_LOST then
    local name = brdcSafeName(event.initiator)
    if name ~= nil then briefingRoom.dynamicCampaign.dead[name] = true end
  end
  if event.id == world.event.S_EVENT_KILL then
    local name = brdcSafeName(event.target)
    if name ~= nil then briefingRoom.dynamicCampaign.dead[name] = true end
  end
  if event.id == world.event.S_EVENT_CRASH or event.id == world.event.S_EVENT_EJECTION or event.id == world.event.S_EVENT_PILOT_DEAD then
    brdcMarkPlayerLost(event.initiator)
  end
  if event.id == world.event.S_EVENT_BIRTH and brdcIsPlayer(event.initiator) then
    brdcTrackFlight(event.initiator, false)
    local okAir, inAir = pcall(function() return event.initiator:inAir() end)
    if okAir and inAir then brdcCheckStock() end -- air start: no takeoff event
  end
  if event.id == world.event.S_EVENT_TAKEOFF and brdcIsPlayer(event.initiator) then
    local name = brdcSafeName(event.initiator)
    -- Loadout as it was at the first takeoff (after any rearming on the ground)
    if name ~= nil and not briefingRoom.dynamicCampaign.tookOff[name] then
      briefingRoom.dynamicCampaign.tookOff[name] = true
      brdcTrackFlight(event.initiator, true)
      brdcCheckStock()
    end
  end
  if event.id == world.event.S_EVENT_MISSION_END then
    briefingRoom.dynamicCampaign.report()
  end
end

function briefingRoom.dynamicCampaign.start()
  local dc = briefingRoom.dynamicCampaign
  for _, objective in ipairs(briefingRoom.mission.objectives) do
    for _, name in ipairs(objective.unitNames or { }) do
      if brdcFindObject(name) ~= nil then dc.tracked[name] = true end
    end
  end

  -- Players already in their aircraft when the mission started
  local okPlayers, players = pcall(function() return coalition.getPlayers(briefingRoom.playerCoalition) end)
  if okPlayers and players ~= nil then
    for _, unit in ipairs(players) do brdcTrackFlight(unit, false) end
  end

  -- Report again whenever an objective is completed
  local completeObjective = briefingRoom.mission.coreFunctions.completeObjective
  briefingRoom.mission.coreFunctions.completeObjective = function(index, failed)
    completeObjective(index, failed)
    pcall(briefingRoom.dynamicCampaign.report)
  end

  dc.report()
  timer.scheduleFunction(function(_, time)
    pcall(briefingRoom.dynamicCampaign.report)
    return time + 60
  end, nil, timer.getTime() + 60)
end

world.addEventHandler(briefingRoom.dynamicCampaign.eventHandler)
timer.scheduleFunction(function() briefingRoom.dynamicCampaign.start() end, nil, timer.getTime() + 2)
